"""Self-contained offline benchmark explorer, with no CDN or server dependency."""
import json
import os
from pathlib import Path


def render_explorer(run_path, output):
    run, output = Path(run_path), Path(output)
    payload = {name: json.loads((run / (name + '.json')).read_text())
               for name in ('summary', 'examples', 'protocol')}
    payload['artifact_base'] = os.path.relpath(run.resolve(), output.parent.resolve())
    encoded = json.dumps(payload, allow_nan=False).replace('&', '\\u0026').replace('<', '\\u003c').replace('>', '\\u003e')
    output.write_text(TEMPLATE.replace('__PAYLOAD__', encoded))
    return output


TEMPLATE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>FloaterFinder · Benchmark explorer</title><style>
:root{color-scheme:light;--ink:#173b44;--muted:#526a73;--line:#dbe5e7;--teal:#007d78}*{box-sizing:border-box}
body{margin:0;background:#f3f6f7;color:var(--ink);font:15px/1.55 system-ui,sans-serif}main{max-width:1300px;margin:auto;padding:32px}h1{font-size:42px;letter-spacing:-1.5px;line-height:1.1;margin:12px 0}h2{font-size:21px;margin:0 0 12px}p{margin:8px 0 16px}.eyebrow{color:var(--teal);font-weight:700;letter-spacing:2px;font-size:12px}.subtitle{color:var(--muted)}
section,.controls{background:white;padding:24px;border:1px solid var(--line);border-radius:12px;margin:18px 0}.notice{padding:16px 20px;background:#fff1cf;border-left:4px solid #b57d20;border-radius:4px;margin:22px 0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat{background:white;border:1px solid var(--line);padding:18px;border-radius:10px}.stat b{display:block;font-size:27px}.stat span{font-size:13px;color:var(--muted)}
.controls{display:flex;gap:18px;flex-wrap:wrap;padding:18px;align-items:end}label{display:flex;flex-direction:column;gap:5px;font-size:13px;font-weight:650}select{background:#fff;border:1px solid #9db4bb;border-radius:6px;padding:9px;font:inherit;color:var(--ink);max-width:100%}.check{display:block;margin:12px 0}.grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:18px}.grid section{margin:0;min-width:0}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:10px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}th{font-size:12px;color:var(--muted)}tr.primary{background:#eaf6f3}.legend{display:flex;flex-wrap:wrap;gap:16px;font-size:12px}svg{width:100%;font:12px system-ui}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.downloads{display:flex;gap:18px;flex-wrap:wrap}a{color:#006963}.note{font-size:13px;color:var(--muted)}#placement svg{max-height:400px}.empty{padding:30px;color:var(--muted)}details{margin:14px 0}summary{cursor:pointer;font-weight:600}
@media(max-width:800px){main{padding:18px}.grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}h1{font-size:34px}.controls label{flex:1;min-width:140px}}@media print{.controls{display:none}main{padding:0}section{break-inside:avoid}body{background:white}}
</style></head><body><main><div class="eyebrow">CACHED EMBEDDINGS / OFFLINE ANALYSIS</div><h1>FloaterFinder</h1><p class="subtitle">Reciprocal contamination, candidate detection, and the cost of removing native tissue.</p>
<div class="notice"><b id="provenance-title">Data provenance</b><div id="provenance"></div><div>Organ classification experiment. These results do not establish clinical floater detection.</div></div><div class="stats" id="stats"></div>
<div class="controls"><label>Model<select id="model"></select></label><label>Pooling<select id="pool"><option value="mean">Mean cosine</option><option value="topk">Per-class top-K</option></select></label><label>Donor context<select id="regime"></select></label><label>Requested dose<select id="dose"></select></label><label>Curve metric<select id="metric"><option value="error_rate_initially_correct">Errors among initially correct</option><option value="detection_recall">Inserted-tile recall</option><option value="detection_precision">Inserted-tile precision</option><option value="host_removal_rate">Host-tile removal</option><option value="recovery_rate">Conditional recovery</option><option value="macro_average_precision">Macro average precision</option><option value="macro_auroc">Macro AUROC</option><option value="accuracy">Organ accuracy</option><option value="abstention_rate">Abstentions</option></select></label></div>
<div class="grid"><section><h2 id="curve-title">Error curves</h2><div id="curve"></div><div id="legend" class="legend"></div><p class="note">X: requested donor / total mixed tiles. Repeated pairs are correlated; lines are descriptive, without confidence intervals. Gaps indicate undefined metrics.</p></section><section><h2>Clean baseline sanity check</h2><div id="baseline"></div><p class="note">Rows are true organs; columns are predictions. The detector receives the stated organ, also this classification target. Recovery measures consistency with supplied context, not independent diagnostic improvement.</p></section></div>
<section><h2>Measurement support</h2><ul id="diagnostics"></ul></section><section><h2>Detection and recovery at selected dose</h2><p id="dose-note" class="note"></p><div class="scroll" id="comparison" aria-live="polite"></div><p class="note">Precision/recall/F1 pool tile counts within this slice; AUROC and AP average per-mixture rankings, with ties grouped. Undefined values are shown as —. Recovery includes only originally correct cases made incorrect by contamination. Filtering all tiles abstains and counts as incorrect. Baselines have no continuous detector ranking.</p></section>
<section><h2>Unmodified-slide harm check</h2><div class="scroll" id="harm"></div><p class="note">Each original slide appears once per model/pooling/detector. Controls are not certified floater-free. Calibration controls pooled tile flags, not the probability that a slide has any flag.</p></section>
<section><h2>Placement and candidate maps</h2><div class="controls"><label>Example<select id="example"></select></label><label>Detector<select id="detector"><option value="combined">Combined</option><option value="organ_only">Organ only</option><option value="visual_only">Visual only</option></select></label></div><label class="check"><input type="checkbox" id="truth"> Reveal inserted-tile ground truth</label><div id="placement"></div><p id="map-note" class="note"></p><p class="note">Teal: tissue tiles. Red outline: detector flag. Gold, when enabled: inserted tissue. Hover for tile ID and score. Coordinate schematics, not histology overlays. HTML includes up to six pairs at each nonzero dose and at most 2000 evenly sampled tiles per map; all directions and tiles are exported. Small regions may be absent from a sampled overview.</p></section>
<section><h2>Results and reproducibility</h2><div class="downloads" id="downloads"></div><details><summary id="skip-title">Skipped scenarios</summary><pre id="skips"></pre></details><details><summary>Frozen protocol and conventions</summary><pre id="protocol"></pre></details><h2>Interpretation limits</h2><ul id="limits"></ul></section><noscript><p>This interactive report needs JavaScript enabled. Read summary.json and curves.csv for numeric results.</p></noscript>
</main><script type="application/json" id="payload">__PAYLOAD__</script><script>
'use strict';
const data=JSON.parse(document.getElementById('payload').textContent), s=data.summary;
const colors={no_filter:'#bd4545',organ_only:'#9c6b17',visual_only:'#7d5eb2',combined:'#007d78',random_matched:'#738391',oracle:'#2866c3'};
const $=id=>document.getElementById(id), esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=x=>x==null?'—':(100*x).toFixed(1)+'%', num=x=>x==null?'—':Number(x).toFixed(3), mean=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;
function options(id,values){const old=$(id).value;$(id).innerHTML=values.map(v=>`<option value="${esc(v.value??v)}">${esc(v.label??v)}</option>`).join('');if(values.some(v=>String(v.value??v)===old))$(id).value=old;}
function table(headers,rows){return '<table><thead><tr>'+headers.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr'+(r[0]==='combined'?' class="primary"':'')+'>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
$('provenance').textContent=s.data_provenance.join(' · ');if(s.data_provenance.some(p=>p.toUpperCase().includes('SYNTHETIC')))$('provenance-title').textContent='SYNTHETIC SOFTWARE DEMONSTRATION';
$('stats').innerHTML=[[s.source_patients,'Source patients'],[s.unordered_source_pairs,'Unordered source pairs'],[s.split,'Evaluation split'],[s.runtime_seconds.toFixed(1)+'s','Benchmark runtime']].map(([n,t])=>`<div class="stat"><b>${esc(n)}</b><span>${esc(t)}</span></div>`).join('');
options('model',[...new Set(s.curves.map(r=>r.model))]);options('regime',[...new Set(s.curves.map(r=>r.regime))]);options('dose',[...new Set(s.curves.map(r=>r.dose))].sort((a,b)=>a-b).map(x=>({value:x,label:pct(x)})));$('dose').selectedIndex=$('dose').options.length-1;
$('diagnostics').innerHTML=(s.diagnostics??[]).map(x=>'<li>'+esc(x)+'</li>').join('')||'<li>No automatic support warnings; this is not a performance approval.</li>';
$('legend').innerHTML=Object.entries(colors).map(([n,c])=>`<span style="color:${c}">● ${esc(n)}</span>`).join('');$('limits').innerHTML=s.limitations.map(x=>'<li>'+esc(x)+'</li>').join('');$('protocol').textContent=JSON.stringify(data.protocol,null,2);$('skip-title').textContent=`Skipped scenarios (${s.skipped_cases.length})`;$('skips').textContent=JSON.stringify(s.skipped_cases,null,2);
$('downloads').innerHTML=['curves.csv','cases.csv','summary.json','tile_artifacts.json','mixtures.json','pairs.json','protocol.json'].map(f=>`<a href="${esc(data.artifact_base+'/'+f)}" download>${esc(f)}</a>`).join('');
function drawCurve(rows){const metric=$('metric').value,maxdose=Math.max(.01,...data.protocol.config.doses),x=d=>55+510*d/maxdose,y=v=>235-205*v;let out='<svg viewBox="0 0 590 285" role="img" aria-label="Benchmark metric versus requested contamination"><path d="M55 25V235H565" fill="none" stroke="#9db4bb"/>';
for(const v of [0,.25,.5,.75,1])out+=`<path d="M55 ${y(v)}H565" stroke="#e5edef"/><text x="7" y="${y(v)+4}">${pct(v)}</text>`;
for(const d of data.protocol.config.doses)out+=`<text x="${x(d)}" y="258" text-anchor="middle">${pct(d)}</text>`;
for(const [method,color] of Object.entries(colors)){let prior=null;for(const r of data.protocol.config.doses.map(d=>rows.find(r=>r.method===method&&r.dose===d)??{dose:d})){const value=r[metric];if(value==null){prior=null;continue;}const point=[x(r.dose),y(value)];if(prior)out+=`<path data-method="${method}" d="M${prior.join(' ')}L${point.join(' ')}" stroke="${color}" fill="none" stroke-width="2"/>`;out+=`<circle cx="${point[0]}" cy="${point[1]}" r="3" fill="${color}"><title>${esc(method)}: ${pct(value)} at ${pct(r.dose)}</title></circle>`;prior=point;}}
out+='<text x="310" y="281" text-anchor="middle">Requested foreign-tile fraction</text></svg>';$('curve').innerHTML=out;$('curve-title').textContent=$('metric').selectedOptions[0].textContent;}
function drawMap(){const ex=data.examples[Number($('example').value)];if(!ex||!$('example').options.length){$('placement').innerHTML='<p class="empty">No stored example for this slice. Check skipped scenarios or the complete tile exports.</p>';$('map-note').textContent='';return;}
const method=$('detector').value,flags=ex.flags?.[method]??ex.flagged,values=ex.signal_scores?.[method]??ex.scores;let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const [x,y] of ex.xy_um){minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);}const scale=Math.min(850/(maxX-minX+ex.tile_size_um),330/(maxY-minY+ex.tile_size_um));let svg='<svg viewBox="0 0 880 360" role="img" aria-label="Tile candidates in physical coordinates">';
ex.xy_um.forEach(([x,y],i)=>{const fill=$('truth').checked&&ex.inserted[i]?'#f0b75a':'#b9dbd8';svg+=`<rect x="${10+(x-minX)*scale}" y="${10+(y-minY)*scale}" width="${ex.tile_size_um*scale}" height="${ex.tile_size_um*scale}" fill="${fill}" stroke="${flags[i]?'#bd3348':'white'}" stroke-width="${flags[i]?2:.4}"><title>${esc(ex.tile_ids?.[i]??i)} · ${esc(method)} ${num(values[i])} · ${flags[i]?'flagged':'unflagged'} · (${num(x)}, ${num(y)}) μm</title></rect>`;});$('placement').innerHTML=svg+'</svg>';$('map-note').textContent=`${ex.host} ← ${ex.donor} · actual dose ${pct(ex.dose)} · ${ex.flagged_counts?.[method]??flags.filter(Boolean).length} / ${ex.total_tiles??flags.length} tiles flagged · showing ${flags.length} tiles${(ex.total_tiles??flags.length)>flags.length?' (sampled overview; use full exports for localization)':''}`;}
function update(){const model=$('model').value,pool=$('pool').value,regime=$('regime').value,dose=Number($('dose').value),rows=s.curves.filter(r=>r.model===model&&r.pooling===pool&&r.regime===regime),chosen=rows.filter(r=>r.dose===dose);drawCurve(rows);
const b=s.sanity[model+'/'+pool];$('baseline').innerHTML=b?`<p>Balanced accuracy <b>${pct(b.balanced_accuracy)}</b></p><div class="scroll">`+table(['True / predicted',...b.labels],b.confusion_matrix.map((r,i)=>[b.labels[i],...r]))+'</div>':'No baseline available';
$('comparison').innerHTML=chosen.length?table(['Method','Cases','Precision','Recall','F1','AUROC','AP','Host removed','Recovery','Eligible recovery','Abstain'],chosen.map(r=>[r.method,r.cases,pct(r.detection_precision),pct(r.detection_recall),pct(r.detection_f1),num(r.macro_auroc),num(r.macro_average_precision),pct(r.host_removal_rate),pct(r.recovery_rate),r.corrupted_correct_cases,pct(r.abstention_rate)])):'<p>No successful mixtures at this dose.</p>';
const r=chosen[0];$('dose-note').textContent=r?`Requested ${pct(dose)} · achieved ${pct(r.actual_dose_min??dose)}–${pct(r.actual_dose_max??dose)} · ${r.initially_correct_cases} initially correct cases · mean unavailable kNN fraction ${pct(r.q2_unavailable_fraction)}. Case counts are mixtures, not independent patients.`:'';
const controls=s.unmodified_controls.filter(c=>c.model===model&&c.pooling===pool);$('harm').innerHTML=table(['Detector','Mean tiles flagged','Slides with any flag','New errors / originally correct','Unavailable kNN'],['organ_only','visual_only','combined'].map(m=>{const a=controls.filter(c=>c.method===m);return [m,pct(mean(a.map(c=>c.flagged_fraction))),pct(mean(a.map(c=>+c.any_flag))),a.filter(c=>c.new_error).length+' / '+a.filter(c=>c.clean_correct).length,pct(mean(a.map(c=>c.q2_unavailable_fraction)))];}));
options('example',data.examples.map((e,i)=>({e,i})).filter(({e})=>e.model===model&&e.regime===regime&&e.requested_dose===dose).map(({e,i})=>({value:i,label:e.host+' ← '+e.donor})));drawMap();}
for(const id of ['model','pool','regime','dose','metric'])$(id).addEventListener('change',update);for(const id of ['example','detector','truth'])$(id).addEventListener('change',drawMap);update();
</script></body></html>'''
